const b = $input.first().json.body || {};
const subject = String(b.subject || ''), body = String(b.body || ''), from = String(b.from || '');
const t = (subject + ' ' + body).toLowerCase();
if (!t.trim()) throw new Error('Empty message');
const has = r => r.test(t);
const category = has(/(refund|reembols|charge|cobran|invoice|fatura|boleto|payment|pagamento)/) ? 'billing'
  : has(/(error|erro|crash|bug|not working|n[aã]o funciona|travou|broken|down|fora do ar)/) ? 'bug'
  : has(/(price|pricing|quote|or[cç]amento|plan|plano|demo|trial)/) ? 'sales'
  : has(/(how|como|where|onde|can i|posso|\?)/) ? 'question' : 'other';
const urgency = has(/(urgent|urgente|asap|immediately|agora|down|fora do ar|lost money|perdi|cannot access|n[aã]o consigo acessar)/) ? 'high' : 'normal';
const neg = has(/(angry|terrible|worst|pessimo|péssimo|horrible|unacceptable|inaceitável|cancel)/);
const pt = has(/(não|nao |você|voce|preciso|olá|obrigad|fatura|cobran|ajuda|por favor)/);
const R = {
  billing: ['We are reviewing the charge on your account and will confirm within one business day.', 'Estamos revisando a cobrança na sua conta e confirmamos em até um dia útil.'],
  bug: ['Sorry about the trouble. Our team is looking into it; could you share a screenshot or the steps to reproduce?', 'Desculpe o transtorno. Nossa equipe está verificando; pode enviar um print ou os passos para reproduzir?'],
  sales: ['Thanks for your interest! Here is a short overview and a link to book a call.', 'Obrigado pelo interesse! Segue um resumo e o link para agendar uma conversa.'],
  question: ['Good question - here is the short answer, and our help center has the full guide.', 'Boa pergunta! Segue a resposta resumida; a central de ajuda tem o guia completo.'],
  other: ['Thanks for writing. A teammate will read this and get back to you.', 'Obrigado pelo contato. Alguém da equipe vai ler e responder.']};
return [{json: {received_at: new Date().toISOString(), from, subject, body, category, urgency: neg && urgency === 'normal' ? 'high' : urgency, sentiment: neg ? 'negative' : 'neutral',
  reply: R[category][pt ? 1 : 0], source: 'rules', lang: pt ? 'pt' : 'en'}}];

const base = $('Rules triage').first().json;
const r = $input.first().json;
try {
  const content = r.choices[0].message.content;
  const a = JSON.parse(content.slice(content.indexOf('{'), content.lastIndexOf('}') + 1));
  if (!['billing','bug','sales','question','other'].includes(a.category)) throw new Error('bad category');
  return [{json: {...base, category: a.category, urgency: a.urgency === 'high' ? 'high' : base.urgency, reply: a.reply || base.reply, source: 'ai'}}];
} catch (e) {
  // Visible fallback: the ticket records that rules were used and why.
  return [{json: {...base, source: 'rules-fallback', ai_error: String(r.error || e.message).slice(0, 120)}}];
}

const q = v => '"' + String(v ?? '').replace(/"/g, '""').replace(/[\r\n]+/g, ' ') + '"';

const j = $input.first().json;
const line = ['received_at','from','subject','category','urgency','sentiment','source','reply'].map(k => q(j[k])).join(',') + '\n';
const bin = await this.helpers.prepareBinaryData(Buffer.from(line, 'utf8'), 'tickets.csv', 'text/plain');
return [{json: j, binary: {data: bin}}];
